use std::{
    fs,
    path::{Path, PathBuf},
    sync::{Arc, RwLock},
};

use argon2::{
    password_hash::{rand_core::OsRng, PasswordHash, PasswordHasher, PasswordVerifier, SaltString},
    Argon2,
};
use rand::{distributions::Alphanumeric, Rng};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

#[derive(Debug, Deserialize)]
struct LegacyApiKeyStore {
    tokens: Vec<LegacyApiKeyRecord>,
}

#[derive(Debug, Deserialize)]
struct LegacyApiKeyRecord {
    id: String,
    #[serde(default = "default_legacy_key_name")]
    name: String,
    secret: String,
    namespace: String,
    scopes: Vec<String>,
}

fn default_legacy_key_name() -> String {
    "managed-instance".to_string()
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiKeyRecord {
    pub id: String,
    pub name: String,
    pub hash: String,
    pub scopes: Vec<String>,
    pub namespaces: Vec<String>,
    #[serde(default)]
    pub revoked: bool,
    /// The worker this credential *is*, when it is a worker credential.
    ///
    /// A key without one authenticates as a service, which is what every key
    /// did before this field existed and what every key without it still does.
    /// A key with one authenticates as `Subject::Worker(worker_id)` and is
    /// thereby **narrower**, not wider: the worker lifecycle routes compare the
    /// authenticated subject against the `worker_id` in the request body, so
    /// such a credential can act as exactly one worker and no other, and cannot
    /// satisfy a check that requires a human or service subject.
    #[serde(default)]
    pub worker_id: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct ApiKeySummary {
    pub id: String,
    pub name: String,
    pub scopes: Vec<String>,
    pub namespaces: Vec<String>,
    pub revoked: bool,
}

#[derive(Debug, Clone)]
pub struct CreatedApiKey {
    pub id: String,
    pub secret: String,
}

#[derive(Debug, Clone)]
pub struct Principal {
    pub key_id: String,
    pub scopes: Vec<String>,
    pub subject_type: String,
    pub identity_id: Option<String>,
    pub session_id: Option<String>,
}

impl Principal {
    pub fn permits(&self, required: &str) -> bool {
        self.scopes
            .iter()
            .any(|scope| scope == "*" || scope == required)
    }
}

#[derive(Clone)]
pub struct KeyStore {
    path: PathBuf,
    records: Arc<RwLock<Vec<ApiKeyRecord>>>,
}

impl KeyStore {
    pub fn load(path: impl Into<PathBuf>) -> Result<Self, String> {
        let path = path.into();
        let (records, migrated) = if path.exists() {
            let bytes = fs::read(&path).map_err(|error| error.to_string())?;
            match serde_json::from_slice::<Vec<ApiKeyRecord>>(&bytes) {
                Ok(records) => (records, false),
                Err(current_error) => {
                    let legacy: LegacyApiKeyStore = serde_json::from_slice(&bytes)
                        .map_err(|_| format!("invalid API key store: {current_error}"))?;
                    let mut records = Vec::with_capacity(legacy.tokens.len());
                    for token in legacy.tokens {
                        let salt = SaltString::generate(&mut OsRng);
                        let hash = Argon2::default()
                            .hash_password(token.secret.as_bytes(), &salt)
                            .map_err(|error| error.to_string())?
                            .to_string();
                        records.push(ApiKeyRecord {
                            id: token.id,
                            name: token.name,
                            hash,
                            scopes: token.scopes,
                            namespaces: vec![token.namespace],
                            revoked: false,
                            // Legacy credentials predate worker identity and
                            // stay services, which is what they already were.
                            worker_id: None,
                        });
                    }
                    (records, true)
                }
            }
        } else {
            (Vec::new(), false)
        };
        let store = Self {
            path,
            records: Arc::new(RwLock::new(records)),
        };
        if migrated {
            store.persist()?;
        }
        Ok(store)
    }

    pub fn authenticate(&self, token: &str, namespace: &str) -> Option<Principal> {
        if !token.starts_with("fdb_live_") || token.len() > 256 {
            return None;
        }
        let records = self.records.read().ok()?;
        records
            .iter()
            // Newly issued high-entropy keys use the fast digest format and
            // are appended to the store. Check them before legacy Argon2
            // records so current requests never pay historical password-hash
            // verification costs.
            .rev()
            .filter(|record| !record.revoked)
            .find_map(|record| {
                let namespace_allowed = record
                    .namespaces
                    .iter()
                    .any(|allowed| allowed == "*" || allowed == namespace);
                if namespace_allowed && verify_api_key(token, &record.hash) {
                    // The credential decides the subject type. A worker
                    // credential can never present as a service and a service
                    // credential can never present as a worker, because neither
                    // the request nor any header participates in this choice.
                    Some(match &record.worker_id {
                        Some(worker) => Principal {
                            key_id: record.id.clone(),
                            scopes: record.scopes.clone(),
                            subject_type: "worker".into(),
                            identity_id: Some(worker.clone()),
                            session_id: None,
                        },
                        None => Principal {
                            key_id: record.id.clone(),
                            scopes: record.scopes.clone(),
                            subject_type: "service".into(),
                            identity_id: None,
                            session_id: None,
                        },
                    })
                } else {
                    None
                }
            })
    }

    pub fn create(
        &self,
        name: String,
        scopes: Vec<String>,
        namespaces: Vec<String>,
    ) -> Result<CreatedApiKey, String> {
        self.create_for_worker(name, scopes, namespaces, None)
    }

    /// Issue a credential that authenticates as one specific worker.
    ///
    /// `worker_id` of `None` produces an ordinary service credential, so this
    /// is the one construction path and [`KeyStore::create`] is the common case
    /// spelled out.
    pub fn create_for_worker(
        &self,
        name: String,
        scopes: Vec<String>,
        namespaces: Vec<String>,
        worker_id: Option<String>,
    ) -> Result<CreatedApiKey, String> {
        let secret: String = rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(48)
            .map(char::from)
            .collect();
        let token = format!("fdb_live_{secret}");
        // Service keys are high-entropy random secrets, not user-selected
        // passwords. A deterministic digest keeps them out of the credential
        // store without imposing Argon2's CPU cost on every API request.
        let hash = hash_api_key(&token);
        let id: String = rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(12)
            .map(char::from)
            .collect();
        self.records
            .write()
            .map_err(|_| "API key store lock poisoned".to_string())?
            .push(ApiKeyRecord {
                id: id.clone(),
                name,
                hash,
                scopes,
                namespaces,
                revoked: false,
                worker_id,
            });
        self.persist()?;
        Ok(CreatedApiKey { id, secret: token })
    }

    pub fn list(&self) -> Result<Vec<ApiKeySummary>, String> {
        Ok(self
            .records
            .read()
            .map_err(|_| "API key store lock poisoned".to_string())?
            .iter()
            .map(|record| ApiKeySummary {
                id: record.id.clone(),
                name: record.name.clone(),
                scopes: record.scopes.clone(),
                namespaces: record.namespaces.clone(),
                revoked: record.revoked,
            })
            .collect())
    }

    pub fn revoke(&self, id: &str) -> Result<bool, String> {
        let found = {
            let mut records = self
                .records
                .write()
                .map_err(|_| "API key store lock poisoned".to_string())?;
            match records.iter_mut().find(|record| record.id == id) {
                Some(record) => {
                    record.revoked = true;
                    true
                }
                None => false,
            }
        };
        if found {
            self.persist()?;
        }
        Ok(found)
    }

    fn persist(&self) -> Result<(), String> {
        if let Some(parent) = self.path.parent() {
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        let temporary = self.path.with_extension("tmp");
        let records = self
            .records
            .read()
            .map_err(|_| "API key store lock poisoned".to_string())?;
        let bytes = serde_json::to_vec_pretty(&*records).map_err(|error| error.to_string())?;
        fs::write(&temporary, bytes).map_err(|error| error.to_string())?;
        fs::rename(&temporary, &self.path).map_err(|error| error.to_string())?;
        Ok(())
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

fn hash_api_key(token: &str) -> String {
    let digest = Sha256::digest(token.as_bytes());
    let encoded = digest
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("sha256:{encoded}")
}

fn verify_api_key(token: &str, stored_hash: &str) -> bool {
    if stored_hash.starts_with("sha256:") {
        let candidate = hash_api_key(token);
        return candidate.len() == stored_hash.len()
            && ring::constant_time::verify_slices_are_equal(
                candidate.as_bytes(),
                stored_hash.as_bytes(),
            )
            .is_ok();
    }

    PasswordHash::new(stored_hash).ok().is_some_and(|parsed| {
        Argon2::default()
            .verify_password(token.as_bytes(), &parsed)
            .is_ok()
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn keys_are_hashed_scoped_and_namespace_bound() {
        let path = std::env::temp_dir().join(format!(
            "feltdb-keys-{}.json",
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let store = KeyStore::load(&path).unwrap();
        let created = store
            .create(
                "test".to_string(),
                vec!["state:read".to_string()],
                vec!["alpha".to_string()],
            )
            .unwrap();
        let token = created.secret;

        let file = fs::read_to_string(&path).unwrap();
        assert!(!file.contains(&token));
        assert!(file.contains("sha256:"));
        assert!(store
            .authenticate(&token, "alpha")
            .unwrap()
            .permits("state:read"));
        assert!(store.authenticate(&token, "beta").is_none());
        assert!(store.authenticate("fdb_live_wrong", "alpha").is_none());
        assert!(store.revoke(&created.id).unwrap());
        assert!(store.authenticate(&token, "alpha").is_none());
        assert!(!store.revoke("missing").unwrap());
        let _ = fs::remove_file(path);
    }

    #[test]
    fn legacy_managed_key_store_is_migrated() {
        let path = std::env::temp_dir().join(format!(
            "feltdb-legacy-keys-{}.json",
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let token = "fdb_live_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUV";
        fs::write(
            &path,
            format!(
                r#"{{"tokens":[{{"id":"default-token","secret":"{token}","namespace":"alpha","scopes":["state:read"],"created_at":"2026-01-01T00:00:00Z","expires_at":"2026-12-31T00:00:00Z"}}]}}"#
            ),
        )
        .unwrap();

        let store = KeyStore::load(&path).unwrap();
        assert!(store.authenticate(token, "alpha").is_some());
        assert!(store.authenticate(token, "beta").is_none());
        let migrated = fs::read_to_string(&path).unwrap();
        assert!(migrated.trim_start().starts_with('['));
        assert!(!migrated.contains(token));
        assert!(migrated.contains("managed-instance"));
        let _ = fs::remove_file(path);
    }

    // ------------------------------------------------------------------
    // Worker identity.
    //
    // The whole worker security boundary rests on one thing: which subject a
    // credential authenticates as. That is decided here, by the stored
    // credential alone — no request field, header or body participates — so
    // these tests are the root of the boundary the workload lifecycle routes
    // enforce further up.
    // ------------------------------------------------------------------

    fn key_store(name: &str) -> (PathBuf, KeyStore) {
        let path = std::env::temp_dir().join(format!(
            "feltdb-worker-identity-{name}-{}-{}.json",
            std::process::id(),
            rand::random::<u64>()
        ));
        let _ = fs::remove_file(&path);
        let store = KeyStore::load(&path).unwrap();
        (path, store)
    }

    #[test]
    fn a_worker_credential_authenticates_as_that_one_worker() {
        let (path, store) = key_store("worker");
        let key = store
            .create_for_worker(
                "extractor".into(),
                vec!["state:read".into()],
                vec!["default".into()],
                Some("worker-x".into()),
            )
            .unwrap();

        let principal = store
            .authenticate(&key.secret, "default")
            .expect("authenticates");
        assert_eq!(principal.subject_type, "worker");
        assert_eq!(
            principal.identity_id.as_deref(),
            Some("worker-x"),
            "the worker it is, not the key it uses, is the identity"
        );
        let _ = fs::remove_file(path);
    }

    #[test]
    fn a_service_credential_cannot_present_as_a_worker() {
        let (path, store) = key_store("service");
        let key = store
            .create(
                "control-plane".into(),
                vec!["state:read".into()],
                vec!["default".into()],
            )
            .unwrap();

        let principal = store
            .authenticate(&key.secret, "default")
            .expect("authenticates");
        assert_eq!(
            principal.subject_type, "service",
            "a key issued without a worker is a service, exactly as before this field existed"
        );
        assert_eq!(principal.identity_id, None);
        let _ = fs::remove_file(path);
    }

    #[test]
    fn worker_identity_survives_a_restart_of_the_credential_store() {
        let (path, store) = key_store("reload");
        let key = store
            .create_for_worker(
                "extractor".into(),
                vec!["state:read".into()],
                vec!["default".into()],
                Some("worker-x".into()),
            )
            .unwrap();
        drop(store);

        // A credential that forgot which worker it was on restart would silently
        // downgrade to a service and start failing the identity check.
        let reopened = KeyStore::load(&path).unwrap();
        let principal = reopened
            .authenticate(&key.secret, "default")
            .expect("authenticates");
        assert_eq!(principal.subject_type, "worker");
        assert_eq!(principal.identity_id.as_deref(), Some("worker-x"));
        let _ = fs::remove_file(path);
    }

    #[test]
    fn a_revoked_worker_credential_authenticates_as_nothing() {
        let (path, store) = key_store("revoked");
        let key = store
            .create_for_worker(
                "extractor".into(),
                vec!["state:read".into()],
                vec!["default".into()],
                Some("worker-x".into()),
            )
            .unwrap();
        assert!(store.revoke(&key.id).unwrap());
        assert!(
            store.authenticate(&key.secret, "default").is_none(),
            "revocation is not weakened by carrying a worker identity"
        );
        let _ = fs::remove_file(path);
    }
}
